Method.Implementation:
$$$TRACE("Inside saveRecordToFile Method")
#dim tSourceFilename,tFilename,tCopyFileName As %String =""
#dim tSC As %Status=$$$OK
Set tSourceFilename=..SForceFilePath_..FileName	

if ..SForceFilePath="" {
	set tSC=$$$ERROR($$$GeneralError,"File Path is not set, Please set the File Path before start the operation. ")
	Quit tSC
}
if '##class(%File).DirectoryExists(..SForceFilePath) {
	do ##class(%File).CreateDirectory(..SForceFilePath)
}
set recFile=##class(%File).%New(tSourceFilename)
do recFile.Open("WSN")

set tCopyFileName=..CopyFilename_$now()	
set tCopyFileName=..SForceFilePath_tCopyFileName	
set tSC=recFile.WriteLine(recData)

if tSC{
	$$$TRACE("Save reord to "_tSourceFilename_"-SUCCESS")		
}else { 
	$$$TRACE($System.Status.GetOneErrorText(tSC)_" - Save reord to "_tSourceFilename_"-FAILED")
}
do recFile.Close()
	If (##class(%File).Exists(tCopyFileName)){ 
		set tSC=$$$ERROR($$$GeneralError,tCopyFileName_" Exists, Kindly look to see why file did not get Sent. ")
	}
	else {
		If (##class(%File).Exists(tSourceFilename)) {
		    set tSC=##class(%File).Rename(tSourceFilename,tCopyFileName)
		}
	}

if tSC{
	$$$TRACE(tSourceFilename_" to "_tCopyFileName_" COPY FILE -SUCCESS")		
}else { 
	$$$TRACE($System.Status.GetOneErrorText(tSC)_" - COPY FAILED")
}

Quit tSC


    if ..SfQueryString="" {
      set ..SfQueryString="Select MasterId__c,Student_ID__c,Social_Security_Number_Last_4__c,lastname,firstname,Birthdate,Email,ReportsToId,CreatedDate,CreatedById,LastModifiedDate,LastModifiedById,Gender__c,Preferred_Name__c,Non_US_National_Identifier__c,Previous_Last_Name__c,Current_Intermountain_Employee__c,Employee_User_Name__c,Employee_Number__c,Facility__c,Rotation_Start_Date__c,Rotation_End_Date__c,RecordType.DeveloperName,ReportsTo.Name,Computer_Access_Needed__c from contact where  Account_Name__c='Intermountain Healthcare Inc' and lastModifiedDate > "
    }
    Set tSC=##class(IHC.ITF.ITFCOMMON.Utility).GetItemSettingValue("Out-SalesForce-Wssc-SOAPWITHFILEIO","InitialQueryStartDate",.iQDt)
    $$$TRACE("InitialQueryStartDate: "_iQDt)
    if iQDt'="" {
	    if ^LatestQDate="" {
           set ^LatestQDate=iQDt
	    }
    }
    else {
	   set ^LatestQDate = $ZDATE($ZTIMESTAMP,3)_"T00:00:00.000Z"
    }

    Set ..Adapter.WebServiceClientClass = "SF.Soap"
    set ..usrNm = ##class(Ens.Config.Credentials).GetValue(..Adapter.Credentials, "Username")
    set ..pswrd = ##class(Ens.Config.Credentials).GetValue(..Adapter.Credentials, "Password")

	Quit tSC
